function db.weatherStrength(Rl)
local Sl=db.fx(Rl)
local Tl=Sl.dmg/Sl.cd/Sl.hp/Sl.speed*(1+(Sl.range-1)/2)
for Ul,Vl in pairs(Sl.kinds)do
Tl=Tl*(1+P.rogueShare(Ul)*Vl)
end
if Sl.ice>0 then
local Wl=P.rogueShare(Skc[1547])
Tl=Tl*(Wl+(1-Wl)/(1-Sl.ice+Sl.ice/V.modFactor(Skc[1576])))
end
if Sl.fly>0 then
Tl=Tl*(1-Sl.fly*0.5)
end
if Sl.noCC then
Tl=Tl*0.95
end
if Sl.shroud then
Tl=Tl*0.9
end
return Tl
end
function db.cardGems(Xl,Yl)
local Zl=0
local am=db.pearlsFrom(Yl+1,50)
for bm,cm in pairs(type(Xl.effects)==Skc[1372]and Xl.effects or{})do
if type(cm)==Skc[1372]then
local dm=tonumber(cm.amount)or 0
if cm.type==Skc[1577]then
Zl=Zl+math.abs(dm)*am*H.pearlValue
elseif cm.type==Skc[1578]then
local em,fm=pcall(N.rewardValue,cm.reward)
if em then
Zl=Zl+(tonumber(fm)or 0)
end
elseif cm.type==Skc[1579]then
Zl=Zl+dm*db.STARFALL_GEMS
elseif cm.type==Skc[1580]then
Zl=Zl+dm*100
end
end
end
if Xl.option_type==Skc[1581]then
Zl=Zl+db.HARD_GEMS
end
if Xl.weather then
local hm=Xl.weather~=db.weatherNow()
if hm and Xl.weather==Skc[1582]then
Zl=Zl+db.STARFALL_GEMS
end
local im=db.board()
if hm and im and Xl.weather~=Skc[1552]and not im.weathers[Xl.weather]then
Zl=Zl+(1000+5000*H.pearlValue+50*(G.ITEM_VALUE.star_remnant_limited or 25))/db.WEATHERS
end
end
return Zl
end
