if#cn.missing>0 then
local tn=cn.missing[1]
table.insert(sn,string.format(Skc[1602],tn.name,tn.unitName))
end
if#hn.units>0 then
table.insert(sn,string.format(Skc[1603],table.concat(hn.units,Skc[1467])))
