function db.skinTick()
if not(H.skinSmart or H.starOpen)or not(I.live.event and db.is(I.live.event.level))then
return
end
if(j.req.back.skins or 0)>L.now()then
return
end
local Nn=G.session()
local function On(Pn,Qn,Rn)
local Sn=j.gameSaid(Qn)
O.pickNote.skins=string.format(Skc[1622],Pn,tostring(Sn or Rn or Skc[1623]))
j.log(1,Skc[1564],O.pickNote.skins)
j.backoff(Skc[1624],1800)
end
local Tn=db.skinPlan()
if H.skinSmart then
local Un=Tn.wear[1]
if Un and(j.req.back.skinWear or 0)<=L.now()then
local Vn=cb.slotOf(Un.unit)
if Vn then
I.str.reequip={uuid=Un.unit,slot=Vn}
j.saveNow()
j.request(Skc[1625],Skc[1626],Un.unit)
local Wn=L.now()
while L.now()-Wn<4 and cb.slotOf(Un.unit)do
task.wait(0.25)
end
end
local Xn=L.now()
local Yn,Zn=j.request(Skc[1627],Skc[1628],Un.uuid,{unit_uuid=Un.unit})
local function ao()
local bo=Nn.collection:get_unit_by_uuid(Un.unit)
return bo and bo.skin~=nil
end
while L.now()-Xn<5 and not ao()do
task.wait(0.25)
end
if Vn then
cb.reequip()
end
if ao()then
j.log(1,Skc[1564],string.format(Skc[1629],Un.name,Un.unitName))
O.pickNote.skins=nil
Tn=db.skinPlan()
else
local co=j.gameSaid(Xn)
O.pickNote.skins=string.format(Skc[1630],Un.name,tostring(co or Zn or Skc[1623]))
j.log(1,Skc[1564],O.pickNote.skins)
j.backoff(Skc[1627],1800)
end
end
if#Tn.sell>0 then
local eo,fo={},0
for go=1,math.min(50,#Tn.sell)do
table.insert(eo,Tn.sell[go].uuid)
fo=fo+Tn.sell[go].pearls
end
local ho=tonumber(G.cur(Skc[1595]))or 0
local io=L.now()
local jo,ko=j.request(Skc[1631],Skc[1632],eo)
while L.now()-io<5 and(tonumber(G.cur(Skc[1595]))or 0)<=ho do
task.wait(0.25)
end
local mo=(tonumber(G.cur(Skc[1595]))or 0)-ho
if mo<=0 then
return On(Skc[1633],io,ko)
end
Q.add(string.format(Skc[1634],#eo),#eo,Skc[1624],string.format(Skc[1635],L.fmt(mo)))
O.pickNote.skins=nil
end
end
if H.starOpen then
local no=Nn.inventory
local function oo()
local po,qo=pcall(no.get_number_of_owned_item,no,db.STAR)
return po and tonumber(qo)or 0
end
local ro=L.now()
for so=1,8 do
if L.now()-ro>15 or not j.alive or j.where~=Skc[1439]then
break
end
local uo=oo()
local vo=db.starPlan(db.skinPlan())
local wo=L.now()
if uo>0 then
local xo,yo=j.request(Skc[1636],Skc[1637],db.STAR,{use10=uo>=10,use_all=false})
while L.now()-wo<6 and oo()>=uo do
task.wait(0.25)
end
if oo()>=uo then
return On(Skc[1638],wo,yo)
end
j.log(1,Skc[1564],string.format(Skc[1639],uo-oo(),(tonumber(((G.prof().capsule_pity_data or{})[db.STAR]or{}).total_opens)or 0)))
O.pickNote.skins=nil
elseif vo.open>0 then
local zo=vo.open>=10 and 10 or 1
local Ao=tonumber(G.cur(Skc[1595]))or 0
local Bo,Co=j.request(Skc[1640],Skc[1641],db.STAR,Skc[1389],Skc[1642],tostring(zo))
while L.now()-wo<5 and oo()<=0 do
task.wait(0.25)
end
if oo()<=0 then
return On(Skc[1643],wo,Co)
end
Q.add(string.format(Skc[1644],oo()),Ao-(tonumber(G.cur(Skc[1595]))or 0),Skc[1645],Skc[1646]..vo.why)
O.pickNote.skins=nil
else
break
end
end
end
end
