end
local Gx=Cx.infinite and math.floor(N.infReach(Skc[1516]..yx)+0.5)or Cx.total
local function Hx(Ix)
local Jx=Cx.configs[Ix]
return xx[Ix]or(type(Jx)==Skc[1372]and xx[Jx.unit_id or Skc[301]])
end
for Kx=1,math.min(Gx or 30,200)do
if Cx.infinite then
local Lx,Mx=pcall(G.LU.Infinite.infinite_amt_scale,Kx,Cx.ld)
local Nx,Ox=0,0
for Px,Qx in pairs(Cx.configs)do
if type(Qx)==Skc[1372]and Qx.spawn_tier_normal then
local Rx,Sx=pcall(G.LU.Infinite.infinite_get_normal_unit_chance,Qx,Kx)
Sx=Rx and tonumber(Sx)or 0
Nx=Nx+Sx
if Hx(Px)then
Ox=Ox+Sx
end
end
end
if Nx>0 then
Ax=Ax+(Lx and tonumber(Mx)or 10)*Ox/Nx
end
else
local Tx=Cx.list[Kx]
for Ux,Vx in ipairs(L.list(Tx and Tx.wave))do
if Hx(Vx.unit)then
Ax=Ax+(tonumber(Vx.amount)or 1)
end
end
end
end
Ax=math.floor(Ax+0.5)
end)
N._spawns[yx]={n=Ax,at=os.time()}
return Ax
end
function N.missionValue(Wx)
local Xx=G.session()
local Yx,Zx=0,nil
for _x,ay in pairs(Xx and Xx.quest_handler.quest_profile_data.quests or{})do
local cy=ay.quest_info
local dy=cy and cy.quest_class
if dy and dy.class==Skc[1789]and type(dy.unit_ids)==Skc[1372]then
local ey=tonumber(dy.amount)or 0
local fy=ey-(tonumber(ay.quest_progress and ay.quest_progress.amount)or 0)
if fy>0 then
local gy=N.levelSpawns(Wx,dy.unit_ids)
if gy>0 then
local hy=tonumber(cy.quest_reward and cy.quest_reward.gem_reward)or 0
for iy,jy in pairs(cy.quest_reward and cy.quest_reward.item or{})do
if type(jy)==Skc[1372]and jy.item_id then
hy=hy+N.itemValue(jy.item_id,tonumber(jy.max_amount or jy.amount or jy.min_amount)or 1)
end
end
Yx=Yx+hy*math.min(1,gy/fy)
Zx=string.format(Skc[1790],tostring(cy.quest_name),L.fmt(ey-fy),L.fmt(ey),L.fmt(math.min(gy,fy)))
end
end
end
end
return Yx,Zx
end
