cb.RELIC_SETTLED_GAIN=2
function cb.relicBar()
if I.str.relicTeam==nil or I.str.relicTeam==N.teamSig()then
return cb.RELIC_SETTLED_GAIN
end
return cb.RELIC_MOVE_GAIN
end
function cb.relicWorth(hD,iD)
local jD=iD._unique_item_data and iD._unique_item_data._unique_relic_data
if not jD then
return 0
end
local kD=G.Items[iD.item_id]or{}
local lD,mD=M.types(hD.unit_id)
if kD.main_damage_type and kD.main_damage_type~=Skc[1837]and kD.main_damage_type~=mD then
return 0
end
local nD,oD=0,0
for pD,qD in pairs(jD._core_damage_type_buffs or{})do
if lD[qD.damage_type]then
nD=nD+(tonumber(qD.mul)or 0)+(tonumber(qD.add_upg)or 0)*0.01+(tonumber(qD.pen)or 0)*0.001
oD=oD+(tonumber(qD.crit)or 0)
end
end
nD=nD+oD*0.5
local rD=M.rows(hD.unit_id)
local sD=rD and rD[rD.max]
local tD=(sD and tonumber(sD.cd)or 0)*M.mult(hD,Skc[1506])
for uD,vD in pairs(jD._unique_relic_effects or{})do
local wD=type(vD.params)==Skc[1372]and vD.params or{}
if vD.id==Skc[1838]then
local xD=math.min(1,(tonumber(wD.extra_damage)or 0)*tD/math.max(1,tonumber(wD.time_interval)or 40))
local yD=M.DRONES and M.DRONES[hD.unit_id]
if yD and yD.late and tD>0 then
local zD=1/tD
xD=xD*zD/(zD+(tonumber(yD.max)or 0)*(tonumber(yD.late.dmg)or 0)*(tonumber(yD.hits)or 1)/math.max(0.1,tonumber(yD.late.cd)or 4))
end
nD=nD+xD
elseif vD.id==Skc[1839]then
nD=nD+(tonumber(wD.dmg_buff)or 0)*0.25
elseif vD.id==Skc[1840]then
nD=nD+(tonumber(wD.dmg_buff)or 0)*oD
elseif vD.id==Skc[1841]then
if lD.magic then
nD=0
else
nD=nD+(tonumber(wD.dmg_buff)or 0)*0.3
end
elseif vD.id==Skc[1842]then
if lD.water_damage then
nD=nD+0.05
end
end
end
return nD
end
function cb.relicPlan()
local AD=G.session()
if not AD then
return nil
end
local BD=AD.inventory and AD.inventory.inventory_profile_data or{}
local CD={}
for DD,ED in ipairs(BD.unique_items or{})do
if type(ED)==Skc[1372]and ED.uuid and(G.Items[ED.item_id]or{}).item_group==Skc[1843]then
table.insert(CD,ED)
end
end
local FD={}
for GD,HD in ipairs(M.equipped())do
local JD=HD.data and HD.data.rarity
if not M.isFarm(HD.id)and(JD==Skc[1599]or JD==Skc[1600]or JD==Skc[1821]or JD==Skc[1844])then
local KD=cb.share(HD.id)
if not I.str.share[HD.id]then
KD=math.min(KD,0.15)
end
local LD={}
for MD,ND in ipairs(CD)do
local OD=cb.relicWorth(HD.u,ND)*KD*100
if OD>0.01 then
table.insert(LD,{it=ND,w=OD})
end
end
table.sort(LD,function(PD,QD)
if PD.w~=QD.w then
return PD.w>QD.w
end
return PD.it.uuid<QD.it.uuid
end)
local RD,SD={},{}
for TD,UD in ipairs(LD)do
local VD=SD[UD.it.item_id]or 0
if#RD<6 and VD<((G.Items[UD.it.item_id]or{}).unique_equip and 1 or 2)then
SD[UD.it.item_id]=VD+1
table.insert(RD,UD)
end
end
if HD.u._equipped_relic then
local WD=false
for XD,YD in ipairs(RD)do
if YD.it.uuid==HD.u._equipped_relic then
WD=true
end
end
local ZD=not WD and AD.inventory:get_item_by_uuid(HD.u._equipped_relic)
if ZD then
table.insert(RD,{it=ZD,w=cb.relicWorth(HD.u,ZD)*KD*100})
end
end
table.insert(FD,{e=HD,share=KD,opts=RD})
end
end
local _D,aE={},-1
local bE,cE,dE={},{},{}
local function eE(fE,gE)
if fE> #FD then
if gE>aE then
aE=gE
_D=table.clone(bE)
end
return
end
local hE=FD[fE]
bE[hE.e.uuid]=nil
eE(fE+1,gE)
for iE,jE in ipairs(hE.opts)do
local kE=(G.Items[jE.it.item_id]or{}).unique_equip
if not cE[jE.it.uuid]and not(kE and dE[jE.it.item_id])then
cE[jE.it.uuid]=true
if kE then
dE[jE.it.item_id]=true
end
bE[hE.e.uuid]=jE.it.uuid
eE(fE+1,gE+jE.w+(jE.it.uuid==hE.e.u._equipped_relic and 0.01 or 0))
bE[hE.e.uuid]=nil
cE[jE.it.uuid]=nil
if kE then
dE[jE.it.item_id]=nil
end
end
end
end
eE(1,0)
local lE,mE=0,{}
for nE,oE in ipairs(FD)do
local pE=oE.e.u._equipped_relic and AD.inventory:get_item_by_uuid(oE.e.u._equipped_relic)
local qE=pE and cb.relicWorth(oE.e.u,pE)*oE.share*100 or 0
lE=lE+qE
local rE=_D[oE.e.uuid]and AD.inventory:get_item_by_uuid(_D[oE.e.uuid])
local sE=rE and cb.relicWorth(oE.e.u,rE)*oE.share*100 or 0
table.insert(mE,string.format(Skc[1845],M.name(oE.e.id),pE and(G.Items[pE.item_id]or{}).name or Skc[1610],qE,rE and(G.Items[rE.item_id]or{}).name or Skc[1610],sE))
end
return _D,aE-lE,mE,FD
end
function cb.relicsApply(tE)
if not(H.team and H.teamRelics)or H.strDry then
return false
end
local uE=N.teamSig()
if not tE and I.str.relicSig==uE and os.time()-(tonumber(I.str.relicAt)or 0)<600 then
return false
end
if j.req.back.relicMove and L.now()<j.req.back.relicMove then
return false
end
I.str.relicSig,I.str.relicAt=uE,os.time()
local vE,wE,xE,yE=cb.relicPlan()
if not vE then
return false
end
I.str.relicNote=string.format(Skc[1846],math.max(0,wE))
if wE<cb.relicBar()then
I.str.relicTeam=uE
return false
end
local zE=G.session()
local AE=zE.profile_data.collection.owned_units
local function BE(CE)
for DE,EE in pairs(AE)do
if EE._equipped_relic==CE then
return DE,EE
end
end
end
local function FE(GE)
return j.gameSaid(GE)or Skc[1623]
end
local function HE(IE)
local JE,KE=BE(IE)
if not JE then
return true
end
local LE=L.now()
j.request(Skc[1847],Skc[1848],IE)
while L.now()-LE<4 and KE._equipped_relic==IE do
task.wait(0.25)
end
task.wait(1.2)
if KE._equipped_relic==IE then
j.log(1,Skc[1827],string.format(Skc[1849],M.name(KE.unit_id),tostring(M.relicName(KE)),FE(LE)))
j.backoff(Skc[1847],300)
return false
end
return true
end
j.log(1,Skc[1827],string.format(Skc[1850],wE,table.concat(xE,Skc[1560])))
for ME,NE in ipairs(yE)do
local OE=NE.e.u._equipped_relic
if OE and OE~=vE[NE.e.uuid]and not HE(OE)then
return false
end
end
for PE,QE in pairs(vE)do
local RE=BE(QE)
if RE and RE~=PE and not HE(QE)then
return false
end
end
table.sort(yE,function(SE,TE)
return SE.share>TE.share
end)
local UE=0
for VE,WE in ipairs(yE)do
local XE=vE[WE.e.uuid]
if XE and WE.e.u._equipped_relic~=XE then
local YE,ZE=0,nil
local _E={}
for aF,bF in ipairs(M.equipped())do
_E[bF.uuid]=true
end
for cF,dF in pairs(AE)do
if dF._equipped_relic then
YE=YE+1
if not _E[cF]and(not ZE or not table.find(I.str.core or{},cF))then
ZE=dF._equipped_relic
end
end
end
if YE>=cb.MAX_RELICS and ZE and not HE(ZE)then
return false
end
local eF=L.now()
j.request(Skc[1847],Skc[1628],XE,{unit_uuid=WE.e.uuid})
while L.now()-eF<4 and WE.e.u._equipped_relic~=XE do
task.wait(0.25)
end
task.wait(1.2)
if WE.e.u._equipped_relic~=XE then
j.log(1,Skc[1827],string.format(Skc[1851],(G.Items[(zE.inventory:get_item_by_uuid(XE)or{}).item_id]or{}).name or Skc[1852],M.name(WE.e.id),FE(eF)))
j.backoff(Skc[1847],300)
I.str.relicAt=0
return false
end
UE=UE+1
end
end
N._sigAt=nil
I.str.relicSig=N.teamSig()
I.str.relicTeam=I.str.relicSig
I.str.relicNote=string.format(Skc[1853],wE)
cb.note(string.format(Skc[1854],UE,wE))
return true
end
function cb.foodHeld()
local fF=G.session()
local gF={}
local hF=fF and fF.inventory and fF.inventory.inventory_profile_data or{}
for iF,jF in pairs(hF.normal_items or{})do
local kF=G.Items[iF]
if type(kF)==Skc[1372]and type(kF.usage)==Skc[1372]and kF.usage.type==Skc[1855]and(tonumber(jF)or 0)>0 then
table.insert(gF,{id=iF,n=tonumber(jF),xp=tonumber(kF.usage.xp_amount)or 0})
end
end
table.sort(gF,function(lF,mF)
return lF.xp>mF.xp
end)
return gF
end
function cb.xpRoom()
local nF,oF=G.session(),0
for pF,qF in ipairs(nF and cb.core()or{})do
local rF=nF.collection:get_unit_by_uuid(qF)
if rF then
oF=oF+math.max(0,cb.xpFor(rF.unit_id,cb.cap(rF))-(tonumber(rF.xp)or 0))
end
end
return oF
end
function cb.plan()
local sF=G.session()
if not sF then
return{}
end
local tF={}
local uF=cb.core()
local vF=cb.foodHeld()
local wF=0
for xF,yF in ipairs(vF)do
wF=wF+yF.n*yF.xp
end
local zF=H.autoFuse and H.fuseUnit~=Skc[301]and H.fuseUnit or nil
local AF=(I.fuseInfo and tonumber(I.fuseInfo.requirement))or(I.lb and tonumber(I.lb.requirement))or 12
local BF=W.have(Skc[1820])
for CF,DF in ipairs(uF)do
local EF=sF.collection:get_unit_by_uuid(DF)
if EF then
local FF,GF=EF.unit_id,M.name(EF.unit_id)
local HF=cb.role(FF)
if H.teamXp and wF>0 then
local IF,JF=cb.gainXp(EF,wF)
local KF,LF=cb.gainXp(EF,500000)
local MF=LF>0 and KF/LF*JF or 0
if JF>0 and MF>0 then
table.insert(tF,{kind=Skc[1856],uuid=DF,name=GF,gain=MF,add=JF,text=string.format(Skc[1857],GF,L.fmt(JF),cb.level(EF),cb.level({unit_id=FF,xp=(tonumber(EF.xp)or 0)+JF}),MF)})
end
end
local NF=I.str.fuseNo and tonumber(I.str.fuseNo[DF])
if H.teamFuse and cb.lb(EF)==0 and HF~=Skc[1390]and DF~=zF and not(NF and os.time()-NF<86400)then
local OF=cb.gainFuse(EF)
local PF=cb.xpFor(FF,cb.cap(EF))<=(tonumber(EF.xp)or 0)
local QF,RF,SF=pcall(O.fuseFuel,EF,AF)
SF=QF and SF or 0
local TF=(not PF and Skc[1858])or(BF<1 and Skc[1859])or(SF<AF and string.format(Skc[1860],math.floor(SF),math.floor(AF)))or nil
table.insert(tF,{kind=Skc[1861],uuid=DF,name=GF,gain=OF,blocked=TF,text=string.format(Skc[1862],GF,OF)})
end
end
end
table.sort(tF,function(UF,VF)
if UF.gain~=VF.gain then
return UF.gain>VF.gain
end
return UF.text<VF.text
end)
for WF in pairs(M._mult)do
if type(WF)==Skc[1374]and WF:sub(1,5)==Skc[1831]then
M._mult[WF]=nil
end
end
I.str.acts,I.str.actsAt={},os.time()
for XF=1,math.min(12,#tF)do
local YF=tF[XF]
table.insert(I.str.acts,{kind=YF.kind,uuid=YF.uuid,name=YF.name,gain=YF.gain,text=YF.text,blocked=YF.blocked})
end
return tF
end
function cb.itemWorth(ZF)
if not(I.str.acts and os.time()-(tonumber(I.str.actsAt)or 0)<900)then
return nil
end
local _F={}
for aG,bG in ipairs(I.str.acts)do
if bG.gain and(not _F[bG.kind]or bG.gain>_F[bG.kind])then
_F[bG.kind]=bG.gain
end
end
local cG=H.strengthValue or 300
if ZF==Skc[1820]then
return _F.fuse and math.max(G.ITEM_VALUE.divine_wish or 400,_F.fuse*cG)or nil
end
return nil
end
function cb.xpRate()
local dG=G.session()
if not dG then
return 0
end
local eG=0
for fG,gG in ipairs(cb.core())do
local hG=dG.collection:get_unit_by_uuid(gG)
if hG then
local iG,jG=cb.gainXp(hG,500000)
if jG>0 then
eG=math.max(eG,iG/jG)
end
end
end
local kG=eG*(H.strengthValue or 300)
if(tonumber(G.cur(Skc[1434]))or 0)>(H.xpGoldFloor or 100000)then
kG=math.min(kG,(G.GOLD_VALUE or 0.02)/14)
end
return kG
end
function cb.xpGuess(lG)
local mG=lG.level and G.Levels[lG.level]
if not mG then
return 0
end
local nG=math.min(9,tonumber(mG.story_world_rank)or tonumber(lG.rank)or 9)
local oG=tonumber(mG.story_level_rank)or 6
local pG=(lG.kind==Skc[1408]and 1.5 or 1)*(nG>5 and 2 or 1)
local qG=2.1564^(nG-1)*(40+10*oG)/pG
if lG.kind==Skc[1391]then
qG=3*30*2.1564^(nG-1)/pG
end
local rG=nG>=9 and 0.3 or(nG>=7 and 0.5 or 1)
return qG*rG*6
end
function cb.modeBonus(sG)
if not(H.team and H.teamXp)or sG.kind==Skc[1392]or sG.kind==Skc[1389]then
return 0
end
local tG=cb._xpRate and os.time()-(cb._xpRateAt or 0)<300 and cb._xpRate or nil
if not tG then
tG=cb.xpRate()
cb._xpRate,cb._xpRateAt=tG,os.time()
end
if tG<=0 then
return 0
end
local uG=I.modes and I.modes[sG.key]
local vG=tonumber(uG and uG.xp)or cb.xpGuess(sG)
local wG=vG*tG
if wG<1 then
return 0
end
return wG,string.format(Skc[1863],L.fmt(vG),math.floor(wG+0.5))
end
function cb.xpSettle()
local xG=I.lastRun
if not(xG and type(xG.xp0)==Skc[1372]and xG.key)then
return
end
local yG=G.session()
if not yG then
return
end
local zG,AG=0,0
for BG,CG in pairs(xG.xp0)do
local EG=yG.collection:get_unit_by_uuid(BG)
if EG then
zG=zG+math.max(0,(tonumber(EG.xp)or 0)-(tonumber(CG)or 0))
AG=AG+1
end
end
I.lastRun=nil
if AG==0 then
return
end
local FG=N.rec(xG.key)
FG.xp=FG.xp and(FG.xp+(zG-FG.xp)*0.3)or zG
if zG>0 then
j.log(2,cb.LOG,string.format(Skc[1864],xG.key,L.fmt(zG)))
end
j.saveSoon()
end
function cb.note(GG)
j.log(1,cb.LOG,GG)
table.insert(I.str.log,1,{at=os.time(),msg=GG})
while#I.str.log>20 do
table.remove(I.str.log)
end
j.saveSoon()
end
function cb.run(HG)
local IG=G.session()
local JG=IG and IG.collection:get_unit_by_uuid(HG.uuid)
if not JG then
return
end
if HG.kind==Skc[1856]then
local KG=M.trait(JG)
local LG=KG==Skc[1865]and 1.5 or 1
local MG=math.max(0,cb.xpFor(JG.unit_id,cb.cap(JG))-(tonumber(JG.xp)or 0))
local NG,OG,PG={},0,0
for QG,RG in ipairs(cb.foodHeld())do
local SG=RG.xp*LG
local TG=math.min(RG.n,math.floor((MG-OG)/math.max(1,SG)))
if TG>0 then
NG[RG.id]=TG
OG=OG+TG*SG
PG=PG+TG
end
end
if PG==0 then
I.str.feedNote=HG.name..Skc[1866]
return
end
local UG,VG=tonumber(JG.xp)or 0,cb.level(JG)
local WG,XG=j.request(Skc[1856],Skc[1867],HG.uuid,NG)
local YG=L.now()
while L.now()-YG<4 and(tonumber((IG.collection:get_unit_by_uuid(HG.uuid)or JG).xp)or 0)<=UG do
task.wait(0.25)
end
local ZG=IG.collection:get_unit_by_uuid(HG.uuid)or JG
local aH=(tonumber(ZG.xp)or 0)-UG
if aH>0 then
Q.add(string.format(Skc[1868],PG,HG.name),PG,Skc[1869],string.format(Skc[1870],L.fmt(aH),VG,cb.level(ZG)))
cb.note(string.format(Skc[1871],HG.name,PG,L.fmt(aH),VG,cb.level(ZG),math.abs(aH-OG)>OG*0.1 and string.format(Skc[1872],L.fmt(OG))or Skc[301]))
else
cb.note(string.format(Skc[1873],HG.name,tostring(WG and XG or Skc[1623])))
j.backoff(Skc[1856],600)
end
elseif HG.kind==Skc[1861]then
O.fuseInto(HG.uuid,false)
end
end
function cb.slotOf(bH)
local cH=G.session()
for dH,eH in pairs(cH and cH.profile_data.collection.equipped_units or{})do
if eH==bH then
return tonumber(dH)or dH
end
end
return nil
end
function cb.reequip()
local fH=I.str.reequip
if not fH then
return true
end
local gH=G.session()
local hH=gH and gH.collection:get_unit_by_uuid(fH.uuid)
if not hH then
I.str.reequip=nil
return true
end
for iH=1,3 do
if cb.slotOf(fH.uuid)then
break
end
j.request(Skc[1874],Skc[1875],fH.uuid)
local jH=L.now()
while L.now()-jH<3 and not cb.slotOf(fH.uuid)do
task.wait(0.25)
end
end
N._sigAt=nil
if cb.slotOf(fH.uuid)then
I.str.reequip=nil
j.saveSoon()
return true
end
j.log(1,Skc[1876],string.format(Skc[1877],M.name(hH.unit_id),tostring(fH.slot)))
return false
end
cb.REMOTE={feed=Skc[1856],fuse=Skc[1861]}
cb.WORK_MAX=300
function cb.nextAct(kH)
local lH=os.time()
for mH,nH in ipairs(kH or{})do
local oH=j.req.back[cb.REMOTE[nH.kind]or Skc[301]]
if not nH.blocked and not(oH and L.now()<oH)and(tonumber(I.str.noWork[nH.kind])or 0)<=lH and(tonumber(I.str.noWork[nH.kind..Skc[1482]..tostring(nH.uuid)])or 0)<=lH then
return nH
end
end
end
function cb.workSig()
local pH=0
for qH,rH in ipairs(cb.foodHeld())do
pH=pH+rH.n
end
return table.concat({pH,W.have(Skc[1820])},Skc[1832])
end
cb.FEED_STOP_GAIN=0.5
function cb.focusReady()
if not(H.autoEvolve and H.evolveUnit~=Skc[301])then
return nil
end
pcall(W.refresh)
for sH,tH in ipairs(I.goals or{})do
if tH.pinned and tH.uuid==H.evolveUnit and tH.ready and(O.evoBlocked[tH.uuid]or 0)<os.time()then
local uH={}
for vH,wH in ipairs(M.equipped())do
uH[wH.uuid]=true
end
if not O.evoEats(tH,uH)then
return tH
end
end
end
end
function cb.hasWork(xH)
if not xH then
local yH=cb.focusReady()
if yH then
return Skc[1878]..M.name(yH.from)..Skc[1879],Skc[1753]
end
if O.snipeWanted()then
return Skc[1880]..M.name(H.snipeUnit)..Skc[1881],Skc[1882]
end
if O.snipeDue()then
return Skc[1883]..M.name(H.snipeUnit)..Skc[1884],Skc[1882]
end
if I.ownSwap then
return Skc[1885]..M.name(I.ownSwap.into)..Skc[1886],Skc[1887]
end
end
if not H.team or H.strDry then
return nil
end
cb.acts=cb.plan()
O.last.teamPlan=L.now()
local zH=cb.acts
if not xH then
zH={}
for AH,BH in ipairs(cb.acts)do
if not(BH.kind==Skc[1856]and(tonumber(BH.gain)or 0)<cb.FEED_STOP_GAIN)then
table.insert(zH,BH)
end
end
end
local CH=cb.nextAct(zH)
if CH then
return CH.text,CH.kind
end
if H.teamRelics and(tonumber(I.str.noWork.relic)or 0)<=os.time()and(not xH or not(H.autoTeam and H.play))then
local DH,EH=cb.relicPlan()
if EH and EH>=(xH and cb.relicBar()or cb.RELIC_SETTLED_GAIN)then
return string.format(Skc[1888],EH),Skc[1889]
end
