end
local Eib=zib(tib)>0
local function Fib(Gib)
local Hib=0
for Iib,Jib in ipairs(Gib)do
if not M.isFarm(Jib.unit_id)and not M.allyBuff(Jib.unit_id)then
Hib=Hib+M.cap(Jib)
end
end
return Hib
end
local Kib
while#wib<6 do
local Lib,Mib
local Nib=Eib and zib(wib)==0
for Oib,Pib in ipairs(tib)do
local Qib=false
for Rib,Sib in ipairs(wib)do
if Sib.unit_id==Pib.unit_id then
Qib=true
end
end
if not Qib and(not Nib or M.isFarm(Pib.unit_id))then
local Tib=table.clone(wib)
table.insert(Tib,Pib)
local Uib=V.run(rib,V.teamFrom(Tib,rib.map),{hpMul=xib})
local Vib=V.objective(Uib)
if not Mib or Vib>Mib then
Lib,Mib,Kib=Pib,Vib,Uib
end
end
end
if not Lib then
break
end
table.insert(wib,Lib)
end
if Eib and zib(wib)==0 then
local Wib,Xib
for Yib=1,#wib do
for Zib,_ib in ipairs(tib)do
if M.isFarm(_ib.unit_id)then
local ajb=table.clone(wib)
ajb[Yib]=_ib
local bjb=V.run(rib,V.teamFrom(ajb,rib.map),{hpMul=xib})
local cjb=V.objective(bjb)
if not Xib or cjb>Xib then
Wib,Xib,Kib=ajb,cjb,bjb
end
end
end
end
if Wib then
wib=Wib
end
end
local function djb(ejb,fjb)
local gjb=V.teamFrom(ejb,rib.map)
return(V.objective(fjb)+V.objective(V.run(rib,gjb,{hpMul=xib*0.92}))+V.objective(V.run(rib,gjb,{hpMul=xib*1.08})))/3
end
local hjb,ijb=Kib or yib,djb(wib,Kib or yib)
