local jjb,kjb
for ljb,mjb in ipairs(wib)do
if not M.isFarm(mjb.unit_id)and not M.allyBuff(mjb.unit_id)then
local njb,ojb=pcall(M.score,mjb,rib.mod)
ojb=(njb and ojb or 0)*M.skinMul(mjb,rib.skinSet)
if not kjb or ojb<kjb then
jjb,kjb=ljb,ojb
end
end
end
if jjb then
local pjb,qjb={},L.now()
for rjb,sjb in ipairs(tib.rest)do
if L.now()-qjb>5 then
break
end
local tjb=false
for ujb,vjb in ipairs(wib)do
if vjb.unit_id==sjb.unit_id then
tjb=true
end
end
if not tjb then
local wjb=table.clone(wib)
wjb[jjb]=sjb
table.insert(pjb,{u=sjb,o=V.objective(V.run(rib,V.teamFrom(wjb,rib.map),{hpMul=xib}))})
end
end
table.sort(pjb,function(xjb,yjb)
return xjb.o>yjb.o
end)
tib=table.clone(tib)
for zjb=1,math.min(4,#pjb)do
table.insert(tib,1,pjb[zjb].u)
end
vib=vib+(L.now()-qjb)
end
end
for Ajb=1,2 do
local Bjb=false
for Cjb=1,#wib do
for Djb,Ejb in ipairs(tib)do
if L.now()-vib>uib then
return wib,hjb,xib,yib
end
local Fjb=false
for Gjb,Hjb in ipairs(wib)do
if Hjb.unit_id==Ejb.unit_id then
Fjb=true
end
end
if not Fjb then
local Ijb=table.clone(wib)
Ijb[Cjb]=Ejb
if(not Eib or zib(Ijb)>0)and Fib(Ijb)>=math.min(8,Fib(wib))then
local Jjb=V.run(rib,V.teamFrom(Ijb,rib.map),{hpMul=xib})
