function P.buildPath()
P.samples={}
local iub=G.PATH and G.PATH.PATH_CACHE and G.PATH.PATH_CACHE[workspace._BASES.pve]
if not iub then
return
end
for jub,kub in pairs(iub)do
if not(G.PATH.HIDDEN_MOCK_LANES and G.PATH.HIDDEN_MOCK_LANES[jub.Name])then
local lub={}
for mub,nub in ipairs(kub.points or{})do
table.insert(lub,nub.part.Position)
end
local oub=0
for pub=2,#lub do
oub=oub+(lub[pub]-lub[pub-1]).Magnitude
end
local qub=0
for rub=2,#lub do
local tub,uub=lub[rub-1],lub[rub]
local vub=(uub-tub).Magnitude
local wub=math.max(1,math.floor(vub/2))
for xub=0,wub-1 do
local yub=tub:Lerp(uub,xub/wub)
table.insert(P.samples,{pos=yub,prog=(qub+vub*xub/wub)/math.max(1,oub),lane=jub.Name})
end
qub=qub+vub
end
if lub[#lub]then
table.insert(P.samples,{pos=lub[#lub],prog=1,lane=jub.Name})
end
end
end
local zub,Aub,Bub={},0,0
for Cub,Dub in ipairs(P.samples)do
local Eub=tostring(Dub.lane)
if not zub[Eub]then
Aub=Aub+1
end
zub[Eub]=(zub[Eub]or 0)+1
Bub=Bub+1
end
P.laneCount={n=Aub,by=zub,avg=Aub>0 and Bub/Aub or 1}
end
