function P.infWave(Jub)
P.infExtend()
if H.trainLeave and not P.stopping then
local Kub,Lub=pcall(P.trainLeave,Jub)
if not Kub then
j.log(1,Skc[1902],Skc[2621]..tostring(Lub))
end
end
if H.infiniteStop and not P.stopping then
local Mub,Nub=pcall(P.infStop,Jub)
if not Mub then
j.log(1,Skc[1902],Skc[2622]..tostring(Nub))
end
end
local Oub=N.infTier(Jub-1)
if Oub<=0 or Oub==P.infTierSeen then
return
end
P.infTierSeen=Oub
task.delay(5,function()
if not j.alive then
return
end
local Pub=G.prof()
local Qub=Pub and Pub.daily_infinite_reward_claims and Pub.daily_infinite_reward_claims[P.ld.id]
local Rub=type(Qub)==Skc[1372]and(tonumber(Qub.highest_claimed_wave)or 0)>=Oub and os.time()-(tonumber(Qub.highest_claim_time)or 0)<900
if Rub then
I.infLive=true
end
j.log(1,Skc[2623],string.format(Skc[2624],Oub,Rub and Skc[2625]or Skc[2626]))
end)
