function P.infStop(Sub)
local Tub=0
for Uub,Vub in ipairs(L.list(G.GS.DAILY_INFINITE_REWARDS))do
Tub=math.max(Tub,tonumber(Vub.wave)or 0)
end
if Tub<=0 or Sub<=Tub+1 then
return
end
local Wub=I.train.on
if P.trainee and Wub and Wub.have+(Wub.got or 0)+(P.trainTk or 0)<Wub.need then
return
end
if not O.every(Skc[2627],60)then
return
end
local Xub=N.rec(P.key)
local Yub=tonumber(Xub.timed)or 0
local Zub=(Yub>0 and(Xub.sec or 0)>0)and math.max(0.5,((Xub.gems or 0)-200*Yub)/(Xub.sec/60))or 2.5
local _ub=pcall(N.pick)
local avb
for bvb,cvb in ipairs(_ub and N.lastScored or{})do
if cvb.kind~=Skc[1391]and(not avb or(cvb.score or 0)>(avb.score or 0))then
avb=cvb
end
end
if not avb or(avb.score or 0)<=Zub then
return
end
P.stopping=true
j.log(1,Skc[2623],string.format(Skc[2628],Sub,Zub,avb.score,avb.label))
P.sellAll()
end
function P.trainLeave(dvb)
local evb=I.train.on
