end
P.trainCount()
local fvb=evb.have+(evb.got or 0)+(P.trainTk or 0)
if fvb<evb.need then
return
end
local gvb,hvb,ivb=pcall(N.infDaily,G.prof(),P.ld.id,(N.infReach(P.key)))
if gvb and(hvb or 0)>0 and ivb>0 and dvb<=ivb then
j.status(Skc[2079],string.format(Skc[2629],M.name(evb.id),evb.what,ivb))
return
end
P.stopping=true
j.log(1,Skc[2623],string.format(Skc[2630],M.name(evb.id),evb.what,L.fmt(fvb),L.fmt(evb.need),dvb))
