function P.lookAt(bHb)
local cHb,dHb=math.huge,nil
for eHb,fHb in ipairs(P.samples)do
local gHb=(L.flat(fHb.pos)-L.flat(bHb)).Magnitude
if gHb<cHb then
cHb,dHb=gHb,fHb.pos
end
end
local hHb=dHb and L.flat(dHb-bHb)or Vector3 .new(0,0,-1)
return hHb.Magnitude>0.01 and hHb.Unit or Vector3 .new(0,0,-1)
end
function P.place(iHb,jHb)
local kHb=M.isFarm(iHb.id)
local lHb,mHb=P.bestSpot(iHb,kHb or(P.random and M.idol(iHb.id)),P.trainee~=nil and iHb.uuid==P.trainee)
if not lHb then
P.noSpot[iHb.uuid]=(P.noSpot[iHb.uuid]or 0)+1
j.status(Skc[2694],Skc[2704]..M.name(iHb.id))
return false
end
local nHb=P.money()
local oHb,pHb=j.request(Skc[2705],Skc[2706],iHb.uuid,G.Util.CFramePLV(lHb,P.lookAt(lHb)))
if oHb and pHb then
P.spent=P.spent+(iHb.data.cost or 0)
table.insert(P.actions,string.format(Skc[2707],M.name(iHb.id)))
j.log(1,Skc[2699],string.format(Skc[2708],M.name(iHb.id),P.spotKey(lHb),mHb,jHb))
P.placeLog=P.placeLog or{}
table.insert(P.placeLog,{t=math.floor(L.now()-(P.startT or L.now())),w=P.wave(),id=iHb.id,x=math.floor(lHb.X),z=math.floor(lHb.Z),cover=math.floor((mHb or 0)+0.5),why=tostring(jHb):sub(1,90)})
j.status(Skc[2694],string.format(Skc[2709],M.name(iHb.id),jHb))
P.placedAt=P.placedAt or{}
P.placedAt[iHb.uuid]=(P.placedAt[iHb.uuid]or 0)+1
return true
end
if nHb>=(iHb.data.cost or 0)and P.random then
P.placeFail=P.placeFail or{}
P.placeFail[iHb.uuid]=(P.placeFail[iHb.uuid]or 0)+1
if P.placeFail[iHb.uuid]>=2 then
P.noSpot[iHb.uuid]=3
j.log(1,Skc[2699],string.format(Skc[2710],M.name(iHb.id),P.fieldCount(),P.FIELD_MAX))
end
end
if oHb and nHb>=(iHb.data.cost or 0)and not P.random then
local qHb=P.spotKey(lHb)
P.refused[qHb]=true
local rHb=P.mapKey()
I.blocked[rHb]=I.blocked[rHb]or{}
if not P.refusedRun[qHb]then
I.blocked[rHb][qHb]=(tonumber(I.blocked[rHb][qHb])or 0)+1
P.refusedRun[qHb]=true
end
P.refusals=(P.refusals or 0)+1
P.unitRefusals[iHb.uuid]=(P.unitRefusals[iHb.uuid]or 0)+1
if P.unitRefusals[iHb.uuid]>=3 then
local sHb=math.max(1,P.count(iHb.uuid))
if I.caps[iHb.uuid]~=sHb then
I.caps[iHb.uuid]=sHb
j.log(1,Skc[2699],string.format(Skc[2711],M.name(iHb.id),sHb))
end
end
j.log(2,Skc[2699],Skc[2712]..qHb..Skc[1770]..M.name(iHb.id))
j.saveSoon()
end
return false
end
function P.count(tHb)
local uHb=0
for vHb,wHb in ipairs({workspace._UNITS,workspace:FindFirstChild(Skc[2713])})do
if wHb then
for xHb,yHb in ipairs(wHb:GetChildren())do
local zHb=yHb:FindFirstChild(Skc[1431])
if zHb and zHb:FindFirstChild(Skc[2702])and zHb.player.Value==F and zHb.uuid.Value==tHb then
uHb=uHb+1
end
end
end
end
return uHb
end
function P.measure()
local AHb,BHb=P.calRun,P.info
if not(AHb and BHb)then
return
end
pcall(P.sampleHelpers)
local CHb=L.now()
local DHb=P.wave()
local EHb=P.money()
if not AHb.start and EHb>0 and#P.mine==0 then
AHb.start=EHb
end
if DHb~=AHb.lastW then
if P.trialId and DHb>0 then
P.trialTrace=P.trialTrace or{}
local FHb,GHb,HHb,IHb=0,{},0,0
for JHb,KHb in ipairs(P.mine)do
local LHb=KHb._stats
if LHb.id.Value==P.trialId then
FHb=FHb+1
table.insert(GHb,tostring(LHb.upgrade.Value))
elseif not M.isFarm(LHb.id.Value)then
IHb=IHb+1
end
end
pcall(P.sampleHelpers,true)
for MHb,NHb in pairs(P.ownDealt)do
if NHb.id==P.trialId then
HHb=HHb+NHb.v
end
end
local OHb=0
for PHb,QHb in pairs(P.helperDealt)do
if QHb.owner==P.trialId then
OHb=OHb+QHb.v
end
end
table.insert(P.trialTrace,string.format(Skc[2714],DHb,CHb-(P.startT or CHb),EHb,table.concat(GHb,Skc[1832]),IHb,HHb+OHb,#(P.enemies or{}),P.hpAliveRaw or 0,P.waveMax[DHb-1]or 0,P.teamDps or 0))
end
if AHb.lastW and AHb.lastW>0 and AHb.lastWT then
table.insert(AHb.waveSec,CHb-AHb.lastWT)
end
if AHb.paidT and DHb>0 and CHb-AHb.paidT<15 then
table.insert(AHb.skip,CHb-AHb.paidT)
end
AHb.paidT=nil
if DHb>0 then
AHb.alive[tostring(DHb)]=P.hpAliveRaw or 0
end
AHb.lastW,AHb.lastWT=DHb,CHb
end
local RHb=workspace:FindFirstChild(Skc[2715])
if RHb and DHb>0 then
AHb.timer[tostring(DHb)]=math.max(AHb.timer[tostring(DHb)]or 0,tonumber(RHb.Value)or 0)
end
local SHb=EHb-(P.lastMoneyR or EHb)
P.lastMoneyR=EHb
P.incomeLog=P.incomeLog or{}
if SHb>0 then
table.insert(P.incomeLog,{t=CHb,y=SHb})
end
while P.incomeLog[1]and CHb-P.incomeLog[1].t>30 do
table.remove(P.incomeLog,1)
end
local THb=0
for UHb,VHb in ipairs(P.incomeLog)do
THb=THb+VHb.y
end
local WHb=math.min(30,CHb-(P.startT or CHb))
P.incomeRate=WHb>=8 and THb/WHb or nil
for XHb,YHb in ipairs(P.enemies)do
local ZHb=YHb.m
local _Hb=P.track[ZHb]
if not _Hb then
local aIb=ZHb._stats
local bIb=ZHb:FindFirstChildOfClass(Skc[2640])
local cIb=BHb.cfgById[aIb.id.Value]
local dIb=cIb and V.baseStats(BHb,cIb)
if bIb and dIb and DHb>0 then
local eIb=dIb*BHb.hpRaw*V.waveScale(BHb,DHb,BHb.list[DHb])
if eIb>0 and bIb.MaxHealth>0 then
table.insert(AHb.hp,bIb.MaxHealth/eIb)
end
end
P.track[ZHb]={t=CHb,p=YHb.prog,sp=(aIb:FindFirstChild(Skc[2716])and tonumber(aIb.speed.Value))or 1}
if DHb>0 then
AHb.spawn[tostring(DHb)]=(AHb.spawn[tostring(DHb)]or 0)+1
AHb.spawnLast[tostring(DHb)]=CHb-(AHb.lastWT or CHb)
end
elseif not _Hb.done and CHb-_Hb.t>=15 then
_Hb.done=true
local fIb=(YHb.prog-_Hb.p)/(CHb-_Hb.t)/math.max(0.1,_Hb.sp)
if fIb>0.001 and YHb.prog<0.95 then
table.insert(AHb.walk,fIb)
end
end
end
local gIb=0
for hIb,iIb in ipairs(P.mine)do
local jIb=iIb._stats:FindFirstChild(Skc[2717])
if jIb then
gIb=gIb+jIb.Value
end
end
AHb.potSum=AHb.potSum or 0
if AHb.lastDealtT then
local kIb=CHb-AHb.lastDealtT
local lIb=0
for mIb,nIb in ipairs(P.mine)do
local oIb=nIb._stats
local pIb=oIb.id.Value
if not M.isFarm(pIb)and oIb:FindFirstChild(Skc[2718])and oIb.target.Value~=nil then
local qIb,rIb=pcall(P.liveDps,nIb,pIb)
if qIb and rIb then
lIb=lIb+rIb*kIb
end
end
end
AHb.potWin=(AHb.potWin or 0)+lIb
if CHb-(AHb.winT or CHb)>=5 then
local sIb=gIb-(AHb.winDealt or gIb)
if AHb.potWin>0 and sIb>=0 then
AHb.dealtSum=(AHb.dealtSum or 0)+sIb
AHb.potSum=AHb.potSum+AHb.potWin
end
AHb.winT,AHb.winDealt,AHb.potWin=CHb,gIb,0
end
end
if not AHb.winT then
AHb.winT,AHb.winDealt=CHb,gIb
end
AHb.lastDealtT=CHb
if DHb~=AHb.dpsW and DHb>0 then
AHb.dpsAt[tostring(DHb)]=P.teamDps or 0
AHb.dpsW=DHb
end
local tIb=math.min(1,CHb-(AHb.densT or CHb))
AHb.densT=CHb
for uIb,vIb in ipairs(P.enemies)do
local wIb=math.min(V.BINS,math.floor(vIb.prog*V.BINS)+1)
AHb.dens[wIb]=(AHb.dens[wIb]or 0)+tIb
end
local xIb=workspace._BASES.player:FindFirstChild(Skc[2719])
local yIb=xIb and xIb:FindFirstChild(Skc[2720])
local zIb=yIb and yIb:FindFirstChildOfClass(Skc[2640])
if zIb then
AHb.baseHp=math.max(AHb.baseHp or 0,zIb.MaxHealth)
local AIb=0
for BIb,CIb in ipairs(P.enemies)do
if CIb.prog>=0.97 then
local DIb=CIb.m:FindFirstChildOfClass(Skc[2640])
AIb=AIb+(DIb and DIb.MaxHealth or CIb.hp)
end
end
if AHb.lastBase and zIb.Health<AHb.lastBase and AIb>0 and AHb.lastBaseT then
table.insert(AHb.baseRel,(AHb.lastBase-zIb.Health)/math.max(0.1,CHb-AHb.lastBaseT)/AIb)
end
AHb.lastBase,AHb.lastBaseT=zIb.Health,CHb
end
end
function P.recordMap()
local EIb=P.mapKey()
local FIb=I.maps[EIb]
if FIb and FIb.v==1 and FIb.laneV and(FIb.densN or 0)==(FIb.binsDensN or 0)then
return
end
if FIb and FIb.v==1 and FIb.laneV and(FIb.densN or 0)>5 and(FIb.binsDensN or 0)>=5 then
return
end
local GIb={override_hitbox_radius=1.75}
local HIb={hill_unit=true,override_hitbox_radius=1.75}
local IIb,JIb={},false
for KIb,LIb in ipairs(P.cands)do
local MIb=P.valid(LIb,GIb)
if MIb then
table.insert(IIb,MIb)
