RIb,SIb=UIb,VIb
end
end
if RIb then
local WIb,XIb={},{}
for YIb=1,V.BINS do
WIb[YIb]=Skc[2480]
end
for ZIb,_Ib in ipairs(PIb or{})do
XIb[_Ib]={}
for aJb=1,V.BINS do
XIb[_Ib][aJb]=Skc[2480]
end
end
local bJb=L.flat(RIb)
for cJb,dJb in ipairs(P.samples)do
if(L.flat(dJb.pos)-bJb).Magnitude<=QIb then
local eJb=math.min(V.BINS,math.floor(dJb.prog*V.BINS)+1)
WIb[eJb]=Skc[1509]
if XIb[tostring(dJb.lane)]then
